import binascii

def unpad(padded_text):
    # Define the padding string used in the original pad function
    padding = 'CryptoHackTheBox'
    padding_len = len(padding)

    # Ensure the padded text is long enough to contain the padding
    if len(padded_text) < padding_len:
        raise ValueError('Padded text too short to contain padding')

    # Extract the suffix of the padded text to check against the padding string
    suffix = padded_text[-padding_len:]

    # Check if the suffix matches the padding string
    if suffix != padding:
        raise ValueError('Malformed padding at the end of the text')

    # Remove the full padding string from the end
    unpadded_text = padded_text[:-padding_len]

    # Calculate the length of the extra padding that was added to make the length a multiple of 16
    extra_padding_length = len(unpadded_text) % 16

    # If there's no extra padding, the entire text before removing the padding string is the original text
    if extra_padding_length == 0:
        return unpadded_text

    # Remove the extra padding
    original_text_length = len(unpadded_text) - extra_padding_length
    return unpadded_text[:original_text_length]

