```cpp
#include <vector>
#include <stdexcept>

// Calculates the minor of a 2x2 matrix.
// Parameters:
// - mat: A 2x2 matrix represented as a vector of vectors.
// - row: The row index of the element whose minor we want to calculate.
// - col: The column index of the element whose minor we want to calculate.
// Returns:
// - The minor value, which is the opposite corner element for a 2x2 matrix.
// Time Complexity: O(1) - Since the operation involves only indexing into a fixed-size array, the time taken is constant.
// Space Complexity: O(1) - No additional space is used beyond the input matrix, making the space complexity constant.

template<typename T>
T minor(const std::vector<std::vector<T>>& mat, std::size_t row, std::size_t col) {
    // Ensure the matrix is 2x2
    if (mat.size() != 2 || mat[0].size() != 2) {
        throw std::invalid_argument("Matrix must be 2x2.");
    }

    // Determine the row index of the minor element
    std::size_t minor_row = (row == 0) ? 1 : 0;
    // Determine the column index of the minor element
    std::size_t minor_col = (col == 0) ? 1 : 0;

    // Return the element at the calculated minor row and column
    return mat[minor_row][minor_col];
}

// Example usage
int main() {
    std::vector<std::vector<int>> matrix = {{4, 6}, {3, 8}};
    try {
        int minorValue = minor(matrix, 0, 0);
        std::cout << "Minor: " << minorValue << std::endl;  // Should output 8
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
```

