        return new THREE.Vector3(u, v, Math.sqrt(u * u + v * v)); // Change this line to plot a different function
    };

    // Generate input values for x and y between -1 and 1 in increments of 0.1
    const step = 0.1;
    const uValues = Array.from({length: 20}, (_, i) => -1 + i * step);
    const vValues = Array.from({length: 20}, (_, i) => -1 + i * step);

