const canvas = document.getElementById('solarSystemCanvas');
const ctx = canvas.getContext('2d');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

function drawPlanet(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fillStyle = color;
    ctx.fill();
    ctx.closePath();
}

function animate() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawPlanet(canvas.width / 2, canvas.height / 2, 50, 'yellow');
    const planets = [{radius: 10, distance: 200, color: 'blue', period: 365}, {radius: 8, distance: 300, color: '#ff7f00', period: 687}];
    planets.forEach((planet, index) => {
        const angle = (Date.now() / 1000) * (360 / planet.period);
        const x = canvas.width / 2 + planet.distance * Math.cos(angle * Math.PI / 180);
        const y = canvas.height / 2 + planet.distance * Math.sin(angle * Math.PI / 180);
        drawPlanet(x, y, planet.radius, planet.color);
    });
    requestAnimationFrame(animate);
}

animate();
```

### Optimization and Enhancement Tips

- **Reduce Redraws**: Clear only the necessary parts of the canvas.
- **Use Efficient Drawing Methods**: Minimize operations within the animation loop.
- **Optimize Rendering**: Ensure the canvas is properly sized to avoid scaling issues.
- **Performance Profiling**: Use browser tools to find bottlenecks.
- **Visual Appeal**: Add subtle animations, shadows, or particle effects.
